package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MinLevelVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property min level of observed source ")
  void test_min_level_v_o_builder() {
    Assertions.assertFalse(MinLevelVO.nullValue().getMinLevel().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MinLevelVO.tryFrom(null).getMinLevel().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", MinLevelVO.from("one").getMinLevel().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MinLevelVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", MinLevelVO.from("one").toString());
  }
}
